import { beforeEach, describe, expect, it, vi } from "vitest";
const { requestHeaders } = vi.hoisted(() => ({ requestHeaders: vi.fn() }));
vi.mock("next/headers", () => ({ headers: requestHeaders }));
import { localizedPrice } from "@/lib/localized-price";
import { PRICE_CONFIG } from "@/lib/pricing";

beforeEach(() => {
  vi.unstubAllEnvs();
  requestHeaders.mockResolvedValue(new Headers());
});
describe("localized public price", () => {
  it.each([
    [{ "x-vercel-ip-country": " in " }, "US", "IN"],
    [{ "cf-ipcountry": "in" }, undefined, "IN"],
    [{ "x-vercel-ip-country": "US", "cf-ipcountry": "IN" }, "IN", "DEFAULT"],
    [{ "x-vercel-ip-country": "XX" }, "IN", "DEFAULT"],
    [{}, undefined, "DEFAULT"],
    [{}, " in ", "IN"],
    [{}, ["IN", "US"], "DEFAULT"],
  ] as const)(
    "resolves headers %o and override %o",
    async (headers, country, key) => {
      vi.stubEnv("NODE_ENV", "development");
      requestHeaders.mockResolvedValue(new Headers(headers));
      expect(
        await localizedPrice(
          Promise.resolve({
            country: Array.isArray(country)
              ? [...country]
              : (country as string | undefined),
          }),
        ),
      ).toBe(PRICE_CONFIG[key]);
    },
  );
  it("ignores local overrides in production", async () => {
    vi.stubEnv("NODE_ENV", "production");
    expect(await localizedPrice(Promise.resolve({ country: "IN" }))).toBe(
      PRICE_CONFIG.DEFAULT,
    );
  });
  it("does not await search parameters when a country header exists", async () => {
    requestHeaders.mockResolvedValue(
      new Headers({ "x-vercel-ip-country": "IN" }),
    );
    expect(await localizedPrice(new Promise(() => {}))).toBe(PRICE_CONFIG.IN);
  });
});

it.each([PRICE_CONFIG.IN, PRICE_CONFIG.DEFAULT])(
  "renders the supplied localized price $symbol$amount in the current pricing cards",
  async (price) => {
    const { createElement } = await import("react");
    const { renderToStaticMarkup } = await import("react-dom/server");
    const { PricingCards } = await import("@/components/pricing/pricing-cards");
    const html = renderToStaticMarkup(
      createElement(PricingCards, {
        price,
        freeAction: null,
        premiumAction: null,
      }),
    );
    expect(html).toContain(
      `<span data-localized-price="true">${price.symbol}${price.amount}</span>`,
    );
    expect(html).toContain(`<span>${price.symbol}0</span>`);
  },
);
